153	interface ParsedOptions {
154	  devices: string[];
155	  from?: number;
156	  to?: number;
157	}
158	
159	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
160	function parseOptions(rest: string[]): ParsedOptions | string {
161	  const devices: string[] = [];
162	  let from: number | undefined;
163	  let to: number | undefined;
164	  for (let i = 0; i < rest.length; i++) {
165	    let opt = rest[i];
166	    let value: string | undefined;
167	    const eq = opt.indexOf('=');
168	    if (opt.startsWith('--') && eq !== -1) {
169	      value = opt.slice(eq + 1);
170	      opt = opt.slice(0, eq);
171	    } else if (opt.startsWith('--')) {
172	      value = rest[i + 1];
173	      if (value === undefined) return `选项 '${opt}' 缺少值`;
174	      i++;
175	    } else {
176	      return `无法识别的参数 '${opt}'`;
177	    }
178	    if (opt === '--device') {
179	      if (value.trim() === '') return "'--device' 的值不能为空";
180	      devices.push(value);
181	    } else if (opt === '--from' || opt === '--to') {
182	      const ts = parseIso8601(value.trim());
183	      if (ts === null) {
184	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
185	      }
186	      if (opt === '--from') from = ts;
187	      else to = ts;
188	    } else {
189	      return `无法识别的选项 '${opt}'`;
190	    }
191	  }
192	  return { devices, from, to };
193	}
194	
195	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
196	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
197	  const out = new Map<string, string[]>();
198	  for (let i = 0; i < rest.length; i++) {
199	    let opt = rest[i];
200	    let value: string | undefined;
201	    const eq = opt.indexOf('=');
202	    if (opt.startsWith('--') && eq !== -1) {
203	      value = opt.slice(eq + 1);
204	      opt = opt.slice(0, eq);
205	    } else if (opt.startsWith('--')) {
206	      value = rest[i + 1];
207	      if (value === undefined) return `选项 '${opt}' 缺少值`;
208	      i++;
209	    } else {
210	      return `无法识别的参数 '${opt}'`;
211	    }
212	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
213	    const list = out.get(opt);
214	    if (list) list.push(value);
215	    else out.set(opt, [value]);
216	  }
217	  return out;
218	}
219	
220	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
221	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
222	  const list = flags.get(name);
223	  if (!list || list.length !== 1) return null;
224	  return list[0];
225	}
226	
227	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
228	function dateFlag(value: string, label: string): number | string {
229	  const ts = parseUtcDate(value.trim());
230	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
231	  return ts;
232	}
233	
234	function cmdRule(rest: string[]): number {
235	  const [sub, ...subrest] = rest;
236	  if (sub === 'list') {
237	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
238	    return cmdRuleList();
239	  }
240	  if (sub === 'create') {
241	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold']);
242	    if (typeof flags === 'string') return usageError(flags);
243	    const idRaw = oneFlag(flags, '--id');
244	    const deviceList = flags.get('--device');
245	    const groupList = flags.get('--group');
246	    const thresholdRaw = oneFlag(flags, '--threshold');
247	    if (idRaw === null || thresholdRaw === null) {
248	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
249	    }
250	    const hasDevice = deviceList !== undefined;
251	    const hasGroup = groupList !== undefined;
252	    if (hasDevice === hasGroup) {
253	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
254	    }
255	    if ((deviceList !== undefined && deviceList.length !== 1) ||
256	      (groupList !== undefined && groupList.length !== 1)) {
257	      return usageError("'rule create' 的目标选项只能出现一次");
258	    }
259	    const id = idRaw.trim();
260	    if (id === '') return usageError('规则标识不能为空');
261	    const thresholdMilli = parseKwh(thresholdRaw.trim());
262	    if (thresholdMilli === null) {
263	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
264	    }
265	    if (hasDevice) {
266	      const device = (deviceList as string[])[0].trim();
267	      if (device === '') return usageError("'--device' 的值不能为空");
268	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli });
269	    }
270	    const group = (groupList as string[])[0].trim();
271	    if (group === '') return usageError("'--group' 的值不能为空");
272	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli });
273	  }
274	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
275	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
276	}
277	
278	function cmdEvaluateEntry(rest: string[]): number {
279	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
280	  if (typeof flags === 'string') return usageError(flags);
281	  const ruleRaw = oneFlag(flags, '--rule');
282	  const fromRaw = oneFlag(flags, '--from');
283	  const toRaw = oneFlag(flags, '--to');
284	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
285	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
286	  }
287	  const ruleId = ruleRaw.trim();
288	  if (ruleId === '') return usageError('规则标识不能为空');
289	  const from = dateFlag(fromRaw, '起始日期');
290	  if (typeof from === 'string') return usageError(from);
291	  const to = dateFlag(toRaw, '结束日期');
292	  if (typeof to === 'string') return usageError(to);
293	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
294	  return cmdEvaluate({ ruleId, from, to });
295	}
296	
297	function cmdAlertsEntry(rest: string[]): number {
298	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
299	  if (typeof flags === 'string') return usageError(flags);
300	  const ruleRaw = oneFlag(flags, '--rule');
301	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
302	  const ruleId = ruleRaw.trim();
303	  if (ruleId === '') return usageError('规则标识不能为空');
304	  const fromList = flags.get('--from');
305	  const toList = flags.get('--to');
306	  if ((fromList !== undefined) !== (toList !== undefined)) {
307	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
308	  }
309	  let from: number | undefined;
310	  let to: number | undefined;
311	  if (fromList !== undefined) {
312	    const fromRaw = oneFlag(flags, '--from');
313	    const toRaw = oneFlag(flags, '--to');
314	    if (fromRaw === null || toRaw === null) {
315	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
316	    }
317	    const fromParsed = dateFlag(fromRaw, '起始日期');
318	    if (typeof fromParsed === 'string') return usageError(fromParsed);
319	    const toParsed = dateFlag(toRaw, '结束日期');
320	    if (typeof toParsed === 'string') return usageError(toParsed);
321	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
322	    from = fromParsed;
323	    to = toParsed;
324	  }
325	  return cmdAlerts({ ruleId, from, to });
326	}
327	
328	function cmdGroup(rest: string[]): number {
329	  const [sub, ...subrest] = rest;
330	  if (sub === 'configure') {
331	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
332	    if (typeof flags === 'string') return usageError(flags);
333	    const idRaw = oneFlag(flags, '--id');
334	    const atRaw = oneFlag(flags, '--at');
335	    const deviceList = flags.get('--device') ?? [];
336	    if (idRaw === null || atRaw === null) {
337	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
338	    }
339	    if (deviceList.length === 0) {
340	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
341	    }
342	    const id = idRaw.trim();
343	    if (id === '') return usageError('分组标识不能为空');
344	    const at = parseIso8601(atRaw.trim());
345	    if (at === null) {
346	      return usageError(
347	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
348	      );
349	    }
350	    const members: string[] = [];
351	    for (const d of deviceList) {
352	      const m = d.trim();
353	      if (m === '') return usageError("'--device' 的值不能为空");
354	      members.push(m);
355	    }
356	    return cmdGroupConfigure({ id, at, members });
357	  }
358	  if (sub === 'history') {
359	    const flags = parseFlags(subrest, ['--id']);
360	    if (typeof flags === 'string') return usageError(flags);
361	    const idRaw = oneFlag(flags, '--id');
362	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
363	    const id = idRaw.trim();
364	    if (id === '') return usageError('分组标识不能为空');
365	    return cmdGroupHistory({ id });
366	  }
367	  if (sub === 'daily') {
368	    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
369	    if (typeof flags === 'string') return usageError(flags);
370	    const idRaw = oneFlag(flags, '--id');
371	    const fromRaw = oneFlag(flags, '--from');
372	    const toRaw = oneFlag(flags, '--to');
373	    if (idRaw === null || fromRaw === null || toRaw === null) {
374	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
375	    }
376	    const id = idRaw.trim();
377	    if (id === '') return usageError('分组标识不能为空');
378	    const from = parseIso8601(fromRaw.trim());
379	    if (from === null) {
380	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
381	    }
382	    const to = parseIso8601(toRaw.trim());
383	    if (to === null) {
384	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
385	    }
386	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
387	    return cmdGroupDaily({ id, from, to });
388	  }
389	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history 或 daily");
390	  return usageError(`无法识别的 group 子命令 '${sub}'`);
391	}
392	
393	/**
394	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
395	 * 各恰好一个。出错返回错误消息字符串。
396	 */
397	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
398	  const segments: string[][] = [[]];
399	  for (const tok of rest) {
400	    if (tok === '--item') segments.push([]);
401	    else segments[segments.length - 1].push(tok);
402	  }
403	  const headFlags = parseFlags(segments[0], ['--request']);
404	  if (typeof headFlags === 'string') return headFlags;
405	  const requestRaw = oneFlag(headFlags, '--request');
406	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
407	  const requestId = requestRaw.trim();
408	  if (requestId === '') return '请求标识不能为空';
409	  const itemSegs = segments.slice(1);
410	  if (itemSegs.length === 0) {
411	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
412	  }
413	  const items: CorrectionItem[] = [];
414	  for (const seg of itemSegs) {
415	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
416	    if (typeof flags === 'string') return flags;
417	    const deviceRaw = oneFlag(flags, '--device');
418	    const atRaw = oneFlag(flags, '--at');
419	    const expectRaw = oneFlag(flags, '--expect');
420	    const setRaw = oneFlag(flags, '--set');
421	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
422	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
423	    }
424	    const device = deviceRaw.trim();
425	    if (device === '') return "'--device' 的值不能为空";
426	    const ts = parseIso8601(atRaw.trim());
427	    if (ts === null) {
428	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
429	    }
430	    const expectedMilli = parseKwh(expectRaw.trim());
431	    if (expectedMilli === null) {
432	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
433	    }
434	    const replacementMilli = parseKwh(setRaw.trim());
435	    if (replacementMilli === null) {
436	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
437	    }
438	    items.push({ device, ts, expectedMilli, replacementMilli });
439	  }
440	  return { requestId, items };
441	}
442	
443	function cmdCorrectEntry(rest: string[]): number {
444	  const parsed = parseCorrectItems(rest);
445	  if (typeof parsed === 'string') return usageError(parsed);
446	  return cmdCorrect(parsed.requestId, parsed.items);
447	}
448	
449	function main(args: string[]): number {
450	  if (args.length === 0) {
451	    console.log(help);
452	    return 0;
453	  }
454	  const [cmd, ...rest] = args;
455	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
456	    console.log(help);
457	    return 0;
458	  }
459	
460	  if (cmd === 'import') {
461	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
462	    return cmdImport(rest[0]);
463	  }
464	
465	  if (cmd === 'readings') {
466	    const parsed = parseOptions(rest);
467	    if (typeof parsed === 'string') return usageError(parsed);
468	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
469	      return usageError('查询起点必须早于终点(--from < --to)');
470	    }
471	    return cmdReadings(parsed);
472	  }
473	
474	  if (cmd === 'daily') {
475	    const parsed = parseOptions(rest);
476	    if (typeof parsed === 'string') return usageError(parsed);
477	    if (parsed.from === undefined || parsed.to === undefined) {
478	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
479	    }
480	    if (parsed.from >= parsed.to) {
481	      return usageError('查询起点必须早于终点(--from < --to)');
482	    }
483	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
484	  }
485	
486	  if (cmd === 'rule') return cmdRule(rest);
487	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
488	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
489	  if (cmd === 'group') return cmdGroup(rest);
490	  if (cmd === 'correct') return cmdCorrectEntry(rest);
491	
492	  if (cmd === 'corrections') {
493	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
494	    return cmdCorrections();
495	  }
496	
497	  if (cmd === 'ack') {
498	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
499	    const alertId = rest[0].trim();
500	    if (alertId === '') return usageError('告警标识不能为空');
501	    return cmdAck(alertId);
502	  }
503	
504	  return usageError(`无法识别的参数 '${cmd}'`);
505	}
506	
507	process.exitCode = main(process.argv.slice(2));
