1	// 本地持久化:JSON 文件,默认位于 ~/.meterwatch/readings.json,
2	// 可用环境变量 METERWATCH_DATA_DIR 指定其他目录。
3	// 写入采用临时文件 + rename 的原子方式;读取失败或内容损坏一律报错,绝不当作空库。
4	//
5	// 毫千瓦时数值在文件中以十进制字符串保存,可表示任意大的精确值;
6	// 同时兼容旧版以 JSON 数值保存的安全整数读数。数值型毫千瓦时若超出
7	// Number 安全整数范围,JSON 解析时已丢失精度,按损坏数据拒绝,不猜测原值。
8	
9	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
10	import { homedir } from 'node:os';
11	import { dirname, join } from 'node:path';
12	
13	export interface Reading {
14	  /** 设备标识(已去除首尾空白,区分大小写)。 */
15	  device: string;
16	  /** 实际时刻,epoch 秒。 */
17	  ts: number;
18	  /** 累计读数,毫千瓦时(千分之一 kWh)BigInt,非负。 */
19	  milli: bigint;
20	}
21	
22	export interface CorrectionItem {
23	  /** 设备标识(已去除首尾空白,区分大小写)。 */
24	  device: string;
25	  /** 实际时刻,epoch 秒。 */
26	  ts: number;
27	  /** 提交时核验的预期原值,毫千瓦时 BigInt。 */
28	  expectedMilli: bigint;
29	  /** 替换值,毫千瓦时 BigInt。 */
30	  replacementMilli: bigint;
31	}
32	
33	export interface Correction {
34	  /** 请求标识(已去除首尾空白,区分大小写),在数据目录内唯一。 */
35	  requestId: string;
36	  /** 本次提交的修正项,按提交顺序保存。 */
37	  items: CorrectionItem[];
38	}
39	
40	export interface StoreData {
41	  readings: Reading[];
42	  /** 已成功提交的修正历史,按提交顺序;与读数同文件原子持久化。 */
43	  corrections: Correction[];
44	}
45	
46	export class StoreError extends Error {}
47	
48	export function dataFilePath(): string {
49	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
50	  return join(dir, 'readings.json');
51	}
52	
53	/** 告警规则与历史的存储文件,与读数文件同目录、相互独立。 */
54	export function alertFilePath(): string {
55	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
56	  return join(dir, 'alerts.json');
57	}
58	
59	/** 分组配置的存储文件,与读数、告警文件同目录、相互独立。 */
60	export function groupFilePath(): string {
61	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
62	  return join(dir, 'groups.json');
63	}
64	
65	/**
66	 * 解析存储中的毫千瓦时字段:十进制数字字符串,或旧格式的安全整数数值。
67	 * 其他形式(含超出安全整数范围的数值,精度已丢失)返回 null,由调用方按损坏处理。
68	 */
69	export function parseStoredMilli(value: unknown): bigint | null {
70	  if (typeof value === 'string' && /^\d+$/.test(value)) return BigInt(value);
71	  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) {
72	    return BigInt(value);
73	  }
74	  return null;
75	}
76	
77	/**
78	 * 解析存储中的修正历史;字段缺失按空历史(旧版文件),存在但结构非法返回 null。
79	 */
80	function parseStoredCorrections(value: unknown): Correction[] | null {
81	  if (value === undefined) return [];
82	  if (!Array.isArray(value)) return null;
83	  const out: Correction[] = [];
84	  const ids = new Set<string>();
85	  for (const c of value as Array<Record<string, unknown>>) {
86	    if (
87	      c === null ||
88	      typeof c !== 'object' ||
89	      typeof c.requestId !== 'string' ||
90	      c.requestId.length === 0 ||
91	      !Array.isArray(c.items) ||
92	      c.items.length === 0 ||
93	      ids.has(c.requestId)
94	    ) {
95	      return null;
96	    }
97	    const items: CorrectionItem[] = [];
98	    for (const it of c.items as Array<Record<string, unknown>>) {
99	      const expectedMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.expectedMilli) : null;
100	      const replacementMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.replacementMilli) : null;
101	      const ok =
102	        it !== null &&
103	        typeof it === 'object' &&
104	        typeof it.device === 'string' &&
105	        it.device.length > 0 &&
106	        Number.isSafeInteger(it.ts) &&
107	        expectedMilli !== null &&
108	        replacementMilli !== null;
109	      if (!ok) return null;
110	      items.push({
111	        device: it.device as string,
112	        ts: it.ts as number,
113	        expectedMilli: expectedMilli as bigint,
114	        replacementMilli: replacementMilli as bigint,
115	      });
116	    }
117	    ids.add(c.requestId);
118	    out.push({ requestId: c.requestId, items });
119	  }
120	  return out;
121	}
