123	/** 读取存储(读数与修正历史);文件不存在返回空数据,存在但无法读取或内容损坏抛出 StoreError。 */
124	export function loadData(path: string): StoreData {
125	  let text: string;
126	  try {
127	    text = readFileSync(path, 'utf8');
128	  } catch (err) {
129	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return { readings: [], corrections: [] };
130	    throw new StoreError(`cannot read storage file ${path}: ${(err as Error).message}`);
131	  }
132	  let data: unknown;
133	  try {
134	    data = JSON.parse(text);
135	  } catch {
136	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
137	  }
138	  const readings = (data as { readings?: unknown })?.readings;
139	  if (!Array.isArray(readings)) {
140	    throw new StoreError(`storage file ${path} is corrupted (missing readings array)`);
141	  }
142	  const out: Reading[] = [];
143	  for (const r of readings as Array<Record<string, unknown>>) {
144	    const milli = r !== null && typeof r === 'object' ? parseStoredMilli(r.milli) : null;
145	    const ok =
146	      r !== null &&
147	      typeof r === 'object' &&
148	      typeof r.device === 'string' &&
149	      r.device.length > 0 &&
150	      Number.isSafeInteger(r.ts) &&
151	      milli !== null;
152	    if (!ok) {
153	      throw new StoreError(`storage file ${path} is corrupted (invalid reading entry)`);
154	    }
155	    out.push({ device: r.device as string, ts: r.ts as number, milli: milli as bigint });
156	  }
157	  const corrections = parseStoredCorrections((data as { corrections?: unknown })?.corrections);
158	  if (corrections === null) {
159	    throw new StoreError(`storage file ${path} is corrupted (invalid corrections)`);
160	  }
161	  return { readings: out, corrections };
162	}
163	
164	/** 只取读数的便捷封装;语义与 loadData 相同。 */
165	export function loadStore(path: string): Reading[] {
166	  return loadData(path).readings;
167	}
