169	/** 原子写入存储(读数与修正历史同文件同时持久化);失败抛错,原有数据保持不变。 */
170	export function saveData(path: string, data: StoreData): void {
171	  mkdirSync(dirname(path), { recursive: true });
172	  const tmp = `${path}.tmp-${process.pid}`;
173	  const body =
174	    JSON.stringify(
175	      {
176	        version: 1,
177	        readings: data.readings.map((r) => ({ device: r.device, ts: r.ts, milli: r.milli.toString() })),
178	        corrections: data.corrections.map((c) => ({
179	          requestId: c.requestId,
180	          items: c.items.map((it) => ({
181	            device: it.device,
182	            ts: it.ts,
