// correct 与 corrections 两个子命令的实现:可追溯的已存读数批量修正。
//
// 一次提交指定非空请求标识及至少一项修正;每项给出设备、实际时刻、预期原读数
// 和替换读数,只修改已有读数的累计值,不新增或删除读数。首次提交逐项核验预期
// 原值与操作前已存值精确一致,全部匹配才整体替换;任一不符整批拒绝,不占用
// 请求标识。读数替换与请求成功记录在同一存储文件中原子持久化,写入失败保留
// 操作前全部状态。同标识同内容重放直接返回原成功结果,不重新校验、不再次
// 替换;同标识异内容报冲突且保持状态。

import {
  dataFilePath,
  loadData,
  saveData,
  StoreError,
  type CorrectionItem,
  type Reading,
} from './store.ts';
import { loadCheckedSeriesByDevice } from './groups.ts';
import { formatIsoUtc } from './time.ts';
import { formatKwh } from './value.ts';

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

function sameItem(a: CorrectionItem, b: CorrectionItem): boolean {
  return (
    a.device === b.device &&
    a.ts === b.ts &&
    a.expectedMilli === b.expectedMilli &&
    a.replacementMilli === b.replacementMilli
  );
}

/** 内容等价:修正项集合相同,顺序无关(时刻已按 epoch 秒、数值已按毫千瓦时规范化)。 */
function itemsEquivalent(a: CorrectionItem[], b: CorrectionItem[]): boolean {
  if (a.length !== b.length) return false;
  const used = new Array<boolean>(b.length).fill(false);
  for (const item of a) {
    let found = false;
    for (let j = 0; j < b.length; j++) {
      if (!used[j] && sameItem(item, b[j])) {
        used[j] = true;
        found = true;
        break;
      }
    }
    if (!found) return false;
  }
  return true;
}

/** 实际改变的读数条数:提交时预期原值已与已存值一致,故替换值不同于预期原值即为改变。 */
function changedCount(items: CorrectionItem[]): number {
  return items.filter((it) => it.expectedMilli !== it.replacementMilli).length;
}

function reportSuccess(requestId: string, items: CorrectionItem[]): void {
  console.log(
    `correction '${requestId}' committed: ${items.length} item(s), ${changedCount(items)} reading(s) changed`,
  );
}

/**
 * 提交一批修正。requestId 与 items 均由调用方完成格式解析(去空白、
 * 时间与数值已规范化)。返回进程退出码。
 */
export function cmdCorrect(requestId: string, items: CorrectionItem[]): number {
  // 同批同一读数身份(设备 + 实际时刻)只允许一项。
  const seen = new Set<string>();
  for (const it of items) {
    const k = `${it.device} ${it.ts}`;
    if (seen.has(k)) {
      err(`duplicate correction item for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
      return 2;
    }
    seen.add(k);
  }

  const storePath = dataFilePath();
  let data;
  try {
    data = loadData(storePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  // 重放:同标识同内容直接返回原成功结果,不重新校验当前读数、不再次替换;
  // 同标识异内容报冲突且保持状态。
  const prior = data.corrections.find((c) => c.requestId === requestId);
  if (prior !== undefined) {
    if (itemsEquivalent(prior.items, items)) {
      reportSuccess(requestId, prior.items);
      return 0;
    }
    err(`correction request '${requestId}' conflicts with an already committed request of the same id; nothing was changed`);
    return 1;
  }

  // 全库重复身份(同一设备同一实际时刻多条存储记录)必须报错,不能当空库。
  let byDevice;
  try {
    byDevice = loadCheckedSeriesByDevice(data.readings);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  // 核验:每项身份必须存在,且预期原值与操作前已存值精确一致。
  const errors: string[] = [];
  const readings: Array<{ reading: Reading; item: CorrectionItem }> = [];
  for (const it of items) {
    const series = byDevice.get(it.device);
    const reading = series?.find((r) => r.ts === it.ts);
    if (reading === undefined) {
      errors.push(`no stored reading for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
      continue;
    }
    if (reading.milli !== it.expectedMilli) {
      errors.push(
        `stored value mismatch for device '${it.device}' at ${formatIsoUtc(it.ts)}: ` +
          `expected ${formatKwh(it.expectedMilli)} kWh but stored ${formatKwh(reading.milli)} kWh`,
      );
      continue;
    }
    readings.push({ reading, item: it });
  }
  if (errors.length > 0) {
    for (const e of errors) err(e);
    err(`correction '${requestId}' rejected: ${errors.length} item(s) failed; nothing was changed`);
    return 1;
  }

  // 整体替换,并把请求成功记录与读数替换同文件原子持久化。
  for (const { reading, item } of readings) reading.milli = item.replacementMilli;
  try {
    saveData(storePath, {
      readings: data.readings,
      corrections: data.corrections.concat([{ requestId, items }]),
    });
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  reportSuccess(requestId, items);
  return 0;
}

/**
 * 按成功提交顺序显示修正历史:请求标识及各项设备、时刻、原值和替换值。
 * 只读,不写入数据。返回进程退出码。
 */
export function cmdCorrections(): number {
  const storePath = dataFilePath();
  let data;
  try {
    data = loadData(storePath);
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  if (data.corrections.length === 0) {
    console.log('no corrections recorded');
    return 0;
  }
  for (const c of data.corrections) {
    console.log(`correction '${c.requestId}': ${c.items.length} item(s), ${changedCount(c.items)} reading(s) changed`);
    for (const it of c.items) {
      console.log(
        `  ${formatIsoUtc(it.ts)}  device=${it.device}  expected=${formatKwh(it.expectedMilli)} kWh  replacement=${formatKwh(it.replacementMilli)} kWh`,
      );
    }
  }
  return 0;
}

content.content:
1	// group 子命令:分组成员版本配置、成员历史查询与分组能耗日报。
2	//
3	// - 分组以首次配置建立,标识非空唯一(去首尾空白、区分大小写);每次配置指定
4	//   生效时刻(含)与一整套已有设备,从该时刻起生效直到下一版本接替;允许乱序
5	//   补录历史版本。成员不能为空,同设备重复列出只算一次,成员顺序不影响等价性,
6	//   设备可属于多个分组。同组同一实际生效时刻、同成员集合重试成功且不新增,
7	//   异成员集合报冲突。
8	// - 配置整次成功或不提交:未知设备、冲突、损坏或不可读存储及写入失败都明确
9	//   报错并保留操作前状态。配置不改读数、规则和告警,导入也不改配置。
10	// - 日报按 UTC 自然日切分(起点含、终点不含,首尾只统计重叠部分),按当时生效
11	//   成员计算,不把最新成员套用到历史;首个版本生效前记为未知。各设备使用完整
12	//   已存时序,区间两端读数即使在查询范围外也参与;成员切换不需要恰好有读数,
13	//   首条读数之前、末条之后及孤立读数时段为未知,不外推。
14	// - 每个时段只有全部生效成员均处于非下降读数区间时才是有效覆盖,并计入成员
15	//   消耗之和;任一成员下降则为异常覆盖,否则任一成员未知则为未知覆盖。异常与
16	//   未知时段不计任何成员消耗,不以缺失设备为零补齐。覆盖秒数按分组实际时间
17	//   计算,不累加成员秒数。各设备片段仍以原读数区间起点累计比例向下取整,
18	//   两端累计量之差为消耗;日界线、查询边界与成员切换均不重置分摊起点,
19	//   拆开查询相加结果一致。全程 BigInt 精确计算,kWh 固定三位小数。
20	// - 日报与历史只读;读取读数时拒绝同设备同一实际时刻的多条存储记录。
21	
22	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
23	import { dirname } from 'node:path';
24	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
25	import { DAY_SECONDS } from './report.ts';
26	import { formatIsoUtc } from './time.ts';
27	import { formatKwh } from './value.ts';
28	
29	export interface GroupVersion {
30	  /** 生效时刻(含),epoch 秒。 */
31	  at: number;
32	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
33	  members: string[];
34	}
35	
36	export interface Group {
37	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
38	  id: string;
39	  /** 成员版本,按生效时刻升序。 */
40	  versions: GroupVersion[];
41	}
42	
43	function err(message: string): void {
44	  console.error(`meterwatch: ${message}`);
45	}
46	
47	/** 读取分组存储;文件不存在返回空数组,存在但无法读取或内容损坏抛出 StoreError。 */
48	export function loadGroups(path: string): Group[] {
49	  let text: string;
50	  try {
51	    text = readFileSync(path, 'utf8');
52	  } catch (e) {
53	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return [];
54	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
55	  }
56	  let data: unknown;
57	  try {
58	    data = JSON.parse(text);
59	  } catch {
60	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
61	  }
62	  const bad = (what: string): StoreError =>
63	    new StoreError(`storage file ${path} is corrupted (${what})`);
64	  const o = data as Record<string, unknown>;
65	  if (o === null || typeof o !== 'object') throw bad('not an object');
66	  if (!Array.isArray(o.groups)) throw bad('missing groups array');
67	
68	  const ids = new Set<string>();
69	  const groups: Group[] = [];
70	  for (const g of o.groups as Array<Record<string, unknown>>) {
71	    const ok =
72	      g !== null &&
73	      typeof g === 'object' &&
74	      typeof g.id === 'string' &&
75	      g.id.length > 0 &&
76	      Array.isArray(g.versions) &&
77	      g.versions.length > 0;
78	    if (!ok) throw bad('invalid group entry');
79	    if (ids.has(g.id as string)) throw bad(`duplicate group id '${g.id}'`);
80	    ids.add(g.id as string);
81	
82	    const versions: GroupVersion[] = [];
83	    const seenAts = new Set<number>();
84	    for (const v of g.versions as Array<Record<string, unknown>>) {
85	      const vok =
86	        v !== null &&
87	        typeof v === 'object' &&
88	        Number.isSafeInteger(v.at) &&
89	        Array.isArray(v.members) &&
90	        v.members.length > 0 &&
91	        (v.members as unknown[]).every((m) => typeof m === 'string' && (m as string).length > 0);
92	      if (!vok) throw bad(`invalid version entry in group '${g.id}'`);
93	      const at = v.at as number;
94	      if (seenAts.has(at)) throw bad(`duplicate version time in group '${g.id}'`);
95	      seenAts.add(at);
96	      const members = [...(v.members as string[])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
97	      for (let i = 1; i < members.length; i++) {
98	        if (members[i] === members[i - 1]) {
99	          throw bad(`duplicate member '${members[i]}' in group '${g.id}'`);
100	        }
101	      }
102	      versions.push({ at, members });
103	    }
104	    versions.sort((a, b) => a.at - b.at);
105	    groups.push({ id: g.id as string, versions });
106	  }
107	  return groups;
108	}
109	
110	/** 原子写入分组存储;失败抛错,原有数据保持不变。 */
111	function saveGroups(path: string, groups: Group[]): void {
112	  mkdirSync(dirname(path), { recursive: true });
113	  const tmp = `${path}.tmp-${process.pid}`;
114	  const body = JSON.stringify({ version: 1, groups }, null, 2) + '\n';
115	  try {
116	    writeFileSync(tmp, body, 'utf8');
117	    renameSync(tmp, path);
118	  } catch (e) {
119	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
120	  }
121	}
122	
123	/**
124	 * 载入读数并按设备分组,各组时序按时刻排序。
125	 * 任一设备(包括未被任何分组引用的设备)同一实际时刻存在多条存储记录时
126	 * 抛 StoreError:新功能拒绝全库重复身份,而不只是成员设备。
127	 */
128	export function loadCheckedSeriesByDevice(all: Reading[]): Map<string, Reading[]> {
129	  const byDevice = new Map<string, Reading[]>();
130	  for (const r of all) {
131	    const list = byDevice.get(r.device);
132	    if (list) list.push(r);
133	    else byDevice.set(r.device, [r]);
134	  }
135	  for (const [device, list] of byDevice) {
136	    list.sort((a, b) => a.ts - b.ts);
137	    for (let i = 1; i < list.length; i++) {
138	      if (list[i].ts === list[i - 1].ts) {
139	        throw new StoreError(
140	          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
141	        );
142	      }
143	    }
144	  }
145	  return byDevice;
146	}
147	
148	/** 在按时刻升序的时序中找最后一条 ts <= s 的下标,无则 -1。 */
149	function floorIndex(series: Reading[], s: number): number {
150	  let lo = 0;
151	  let hi = series.length - 1;
152	  let ans = -1;
153	  while (lo <= hi) {
154	    const mid = (lo + hi) >> 1;
155	    if (series[mid].ts <= s) {
156	      ans = mid;
157	      lo = mid + 1;
158	    } else {
159	      hi = mid - 1;
160	    }
161	  }
162	  return ans;
163	}
164	
165	type SliceKind = 'valid' | 'anomaly' | 'unknown';
166	
167	/**
168	 * 单设备在片段 [s, e) 上的状态与消耗。片段完全落在同一读数区间内
169	 * (调用方保证切点包含区间内全部读数时刻)。非下降区间以区间起点累计
170	 * 比例向下取整,消耗为两端累计量之差;下降区间为异常;首条读数之前、
171	 * 末条之后及孤立读数时段为未知,不外推。
172	 */
173	function deviceSlice(
174	  series: Reading[],
175	  s: number,
176	  e: number,
177	): { kind: SliceKind; consumption: bigint } {
178	  const i = floorIndex(series, s);
179	  if (i < 0 || i + 1 >= series.length) return { kind: 'unknown', consumption: 0n };
180	  const a = series[i];
181	  const b = series[i + 1];
182	  const diff = b.milli - a.milli;
183	  if (diff < 0n) return { kind: 'anomaly', consumption: 0n };
184	  const duration = BigInt(b.ts - a.ts);
185	  const cumulative = (t: number): bigint => (diff * BigInt(t - a.ts)) / duration;
186	  return { kind: 'valid', consumption: cumulative(e) - cumulative(s) };
187	}
188	
189	export interface GroupPeriod {
190	  /** 时段起点(含),epoch 秒。 */
191	  start: number;
192	  /** 时段终点(不含),epoch 秒。 */
193	  end: number;
194	  /** 该时段生效成员;null 表示首个版本生效前(未知)。 */
195	  members: string[] | null;
196	}
197	
198	export interface GroupSegmentStats {
199	  /** 有效(全部成员非下降)覆盖秒数,按分组实际时间计。 */
200	  valid: number;
201	  /** 异常(任一成员下降)覆盖秒数。 */
202	  anomaly: number;
203	  /** 未知(无生效版本或任一成员未知)覆盖秒数。 */
204	  unknown: number;
205	  /** 有效时段内全部生效成员的分摊消耗之和,毫千瓦时 BigInt。 */
206	  consumption: bigint;
207	  /** 段内按生效时刻切分的成员时段。 */
208	  periods: GroupPeriod[];
209	}
210	
211	/**
212	 * 计算分组在 [segStart, segEnd) 上的覆盖与消耗。
213	 * versions 按生效时刻升序;seriesByDevice 含全部版本成员的完整时序。
214	 */
215	export function computeGroupSegment(
216	  versions: GroupVersion[],
217	  seriesByDevice: Map<string, Reading[]>,
218	  segStart: number,
219	  segEnd: number,
220	): GroupSegmentStats {
221	  // 按版本生效时刻把段切成成员恒定的时段;首个版本生效前 members 为 null。
222	  const periods: GroupPeriod[] = [];
223	  let idx = -1;
224	  for (let i = 0; i < versions.length; i++) {
225	    if (versions[i].at <= segStart) idx = i;
226	    else break;
227	  }
228	  let cursor = segStart;
229	  while (cursor < segEnd) {
230	    const nextAt = idx + 1 < versions.length ? versions[idx + 1].at : Number.POSITIVE_INFINITY;
231	    const pEnd = Math.min(segEnd, nextAt);
232	    periods.push({ start: cursor, end: pEnd, members: idx >= 0 ? versions[idx].members : null });
233	    cursor = pEnd;
234	    idx++;
235	  }
236	
237	  let valid = 0;
238	  let anomaly = 0;
239	  let unknown = 0;
240	  let consumption = 0n;
241	  for (const p of periods) {
242	    if (p.members === null) {
243	      unknown += p.end - p.start;
244	      continue;
245	    }
246	    // 切点:时段边界与全部成员的读数时刻;相邻切点间每个成员的状态恒定。
247	    const bounds = new Set<number>([p.start, p.end]);
248	    for (const m of p.members) {
249	      for (const r of seriesByDevice.get(m) ?? []) {
250	        if (r.ts > p.start && r.ts < p.end) bounds.add(r.ts);
251	      }
252	    }
253	    const sorted = [...bounds].sort((a, b) => a - b);
254	    for (let k = 0; k + 1 < sorted.length; k++) {
255	      const s = sorted[k];
256	      const e = sorted[k + 1];
257	      let anyAnomaly = false;
258	      let anyUnknown = false;
259	      let slice = 0n;
260	      for (const m of p.members) {
261	        const res = deviceSlice(seriesByDevice.get(m) ?? [], s, e);
262	        if (res.kind === 'anomaly') anyAnomaly = true;
263	        else if (res.kind === 'unknown') anyUnknown = true;
264	        else slice += res.consumption;
265	      }
266	      if (anyAnomaly) {
267	        anomaly += e - s;
268	      } else if (anyUnknown) {
269	        unknown += e - s;
270	      } else {
271	        valid += e - s;
272	        consumption += slice;
273	      }
274	    }
275	  }
276	  return { valid, anomaly, unknown, consumption, periods };
277	}
278	
279	/**
280	 * 配置分组成员版本。首次配置即建立分组;同组同一实际生效时刻、同成员集合
281	 * 重试成功且不新增,异成员集合报冲突。整次成功或不提交。返回进程退出码。
282	 */
283	export function cmdGroupConfigure(opts: { id: string; at: number; members: string[] }): number {
284	  const path = groupFilePath();
285	  let groups: Group[];
286	  try {
287	    groups = loadGroups(path);
288	  } catch (e) {
289	    if (e instanceof StoreError) {
290	      err(e.message);
291	      return 1;
292	    }
293	    throw e;
294	  }
295	
296	  // 规范形:同设备重复列出只算一次,成员顺序不影响等价性。
297	  const members = [...new Set(opts.members)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
298	
299	  let known: Set<string>;
300	  try {
301	    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
302	  } catch (e) {
303	    if (e instanceof StoreError) {
304	      err(e.message);
305	      return 1;
306	    }
307	    throw e;
308	  }
309	  for (const m of members) {
310	    if (!known.has(m)) {
311	      err(`unknown device '${m}': no stored readings; import readings before configuring a group`);
312	      return 1;
313	    }
314	  }
315	
316	  const existing = groups.find((g) => g.id === opts.id);
317	  if (existing) {
318	    const v = existing.versions.find((ver) => ver.at === opts.at);
319	    if (v) {
320	      const same =
321	        v.members.length === members.length && v.members.every((m, i) => m === members[i]);
322	      if (same) {
323	        console.log(
324	          `group '${opts.id}' already has an identical member version at ${formatIsoUtc(opts.at)}; unchanged`,
325	        );
326	        return 0;
327	      }
328	      err(
329	        `group '${opts.id}' already has a different member version at ${formatIsoUtc(opts.at)} ` +
330	          `(stored members=${v.members.join(',')}, got members=${members.join(',')}); conflict`,
331	      );
332	      return 1;
333	    }
334	    existing.versions.push({ at: opts.at, members });
335	    existing.versions.sort((a, b) => a.at - b.at);
336	  } else {
337	    groups.push({ id: opts.id, versions: [{ at: opts.at, members }] });
338	  }
339	
340	  try {
341	    saveGroups(path, groups);
342	  } catch (e) {
343	    if (e instanceof StoreError) {
344	      err(e.message);
345	      return 1;
346	    }
347	    throw e;
348	  }
349	  console.log(
350	    `group '${opts.id}' configured: members=${members.join(',')} effective ${formatIsoUtc(opts.at)}`,
351	  );
352	  return 0;
353	}
354	
355	/** 查看分组成员版本历史,按生效时刻排序。只读。返回进程退出码。 */
356	export function cmdGroupHistory(opts: { id: string }): number {
357	  let groups: Group[];
358	  try {
359	    groups = loadGroups(groupFilePath());
360	  } catch (e) {
361	    if (e instanceof StoreError) {
362	      err(e.message);
363	      return 1;
364	    }
365	    throw e;
366	  }
367	  const group = groups.find((g) => g.id === opts.id);
368	  if (!group) {
369	    err(`unknown group '${opts.id}'`);
370	    return 1;
371	  }
372	  console.log(`group: ${group.id}`);
373	  for (const v of group.versions) {
374	    console.log(`  ${formatIsoUtc(v.at)}  members=${v.members.join(',')}`);
375	  }
376	  return 0;
377	}
378	
379	/**
380	 * 分组能耗日报:按 UTC 自然日切分,按当时生效成员计算。只读,不写入数据。
381	 * 返回进程退出码。
382	 */
383	export function cmdGroupDaily(opts: { id: string; from: number; to: number }): number {
384	  let groups: Group[];
385	  try {
386	    groups = loadGroups(groupFilePath());
387	  } catch (e) {
388	    if (e instanceof StoreError) {
389	      err(e.message);
390	      return 1;
391	    }
392	    throw e;
393	  }
394	  const group = groups.find((g) => g.id === opts.id);
395	  if (!group) {
396	    err(`unknown group '${opts.id}'`);
397	    return 1;
398	  }
399	
400	  let seriesByDevice: Map<string, Reading[]>;
401	  try {
402	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
403	  } catch (e) {
404	    if (e instanceof StoreError) {
405	      err(e.message);
406	      return 1;
407	    }
408	    throw e;
409	  }
410	
411	  console.log(`group: ${group.id}`);
412	  let total = 0n;
413	  let computedDays = 0;
414	  let days = 0;
415	  let incomplete = false;
416	  for (
417	    let dayStart = Math.floor(opts.from / DAY_SECONDS) * DAY_SECONDS;
418	    dayStart < opts.to;
419	    dayStart += DAY_SECONDS
420	  ) {
421	    const segStart = Math.max(dayStart, opts.from);
422	    const segEnd = Math.min(dayStart + DAY_SECONDS, opts.to);
423	    const stats = computeGroupSegment(group.versions, seriesByDevice, segStart, segEnd);
424	    days++;
425	
426	    const date = formatIsoUtc(dayStart).slice(0, 10);
427	    const dayIncomplete = stats.anomaly > 0 || stats.unknown > 0;
428	    if (dayIncomplete) incomplete = true;
429	
430	    let consumption: string;
431	    if (stats.valid > 0) {
432	      consumption = `consumption=${formatKwh(stats.consumption)} kWh (estimate)`;
433	      total += stats.consumption;
434	      computedDays++;
435	    } else {
436	      consumption = 'consumption=n/a (no valid coverage)';
437	    }
438	    let line =
439	      `  ${date}  ${consumption}` +
440	      `  valid=${stats.valid}s  anomaly=${stats.anomaly}s  unknown=${stats.unknown}s`;
441	    if (dayIncomplete) line += '  INCOMPLETE';
442	    console.log(line);
443	    for (const p of stats.periods) {
444	      const members = p.members === null ? '(no version in effect)' : p.members.join(',');
445	      console.log(
446	        `    members=${members}  period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`,
447	      );
448	    }
449	  }
450	
451	  const totalText =
452	    computedDays > 0
453	      ? `total consumption=${formatKwh(total)} kWh (estimate)`
454	      : 'total consumption=n/a (no valid coverage)';
455	  const status = incomplete
456	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
457	    : 'status=complete';
458	  console.log(
459	    `  summary: group=${group.id}  computed=${computedDays}/${days} day(s)  ${totalText}  ${status}`,
460	  );
461	  return 0;
462	}
